import { TransferList, type TransferListValueDetail } from '@absoluteui/components/transfer-list';

const host = document.createElement('div');
const summary = document.createElement('p');
document.body.append(host, summary);
TransferList.create(host, {
  label: 'Project team',
  name: 'members',
  required: true,
  items: [
    { value: 'e1', label: 'Asha Rao', description: 'Engineering' },
    { value: 'e2', label: 'Ben Okafor', description: 'Design' },
    { value: 'e3', label: 'Chen Wei', description: 'Engineering' },
    { value: 'e4', label: 'Dana Silva', description: 'On leave', disabled: true },
  ],
  value: ['e2'],
  titles: { available: 'Employees', selected: 'Team' },
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<TransferListValueDetail>).detail;
  summary.textContent = `${String(value.length)} members`;
});

import { TransferList } from '@absoluteui/components/transfer-list';

const host = document.createElement('div');
document.body.append(host);
const items = Array.from({ length: 10_000 }, (_, i) => ({ value: `sku-${String(i)}`, label: `Product ${String(i + 1)}` }));
TransferList.create(host, { label: 'Featured products', items, maxSelected: 12, draggable: true, visibleRows: 10 });

